	{ "result", "A saved scene with a posed character, light and a camera, ready to render or animate.",
		"Сохранённая сцена с позированным персонажем, светом и камерой — её можно рендерить или анимировать." },
	{ "see", "first_anim", "the same, continued into an animation and a video", "то же самое, но дальше — анимация и видео" },
	{ "see", "interface", "what is where in the editor", "что где в редакторе" },
	{ "try", "Open the model browser", "Открыть браузер моделей", fn = function() UI.ToggleBrowser() end },
} })

-- an example scene: asks first when the current scene has objects (loading replaces it)
local function loadExample(name)
	if #C.Objects() == 0 then
		C.SceneLoad(name)
		return
	end
	Derma_Query(string.format(L("load_confirm"), name), "SPeditor", L("load"), function() C.SceneLoad(name) end, L("cancel"), function() end)
end

