UI.AddGuide({ id = "posing", order = 2, icon = "icon16/arrow_rotate_clockwise.png", title = { en = "Posing: move, turn, IK, stretch, locks", ru = "Позирование: перенос, поворот, IK, растяжение, замки" }, blocks = {
